-- =============================================
-- BASE DE DONNEES : CALENDRIER DES EXAMENS
-- =============================================

CREATE DATABASE IF NOT EXISTS calendrier_examens CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE calendrier_examens;

-- ----------------------------
-- TABLE : professeur
-- ----------------------------
CREATE TABLE professeur (
    id_professeur INT PRIMARY KEY AUTO_INCREMENT,
    nom_professeur VARCHAR(100) NOT NULL
);

-- ----------------------------
-- TABLE : filiere
-- ----------------------------
CREATE TABLE filiere (
    id_filiere INT PRIMARY KEY AUTO_INCREMENT,
    nom_filiere VARCHAR(100) NOT NULL,
    annee TINYINT NOT NULL COMMENT '1=1ère année, 2=2ème année, 3=3ème année',
    CHECK (annee IN (1, 2, 3))
);

-- ----------------------------
-- TABLE : matiere
-- ----------------------------
CREATE TABLE matiere (
    id_matiere INT PRIMARY KEY AUTO_INCREMENT,
    nom_matiere VARCHAR(200) NOT NULL,
    id_professeur INT NOT NULL,
    id_filiere INT NOT NULL,
    jour TINYINT NOT NULL COMMENT '1=Lundi, 2=Mardi, 3=Mercredi, 4=Jeudi, 5=Vendredi, 6=Samedi',
    type_examen VARCHAR(20) NOT NULL COMMENT 'DS=Devoir Surveillé, Examen=Session Principale',
    FOREIGN KEY (id_professeur) REFERENCES professeur(id_professeur),
    FOREIGN KEY (id_filiere) REFERENCES filiere(id_filiere)
);

